// landed — no preview, no way to nudge it. Now a tap STAGES the placement: the ghost
// can be dragged around and only the Place button commits it.
let pending = null, pendingFort = false;
function pendingHit(tx,ty){
  if(!pending) return false;
  const rx=Math.round(tx), ry=Math.round(ty);
  if(bodyTiles(pending[0],pending[1],pendingFort).some(([bx,by])=>bx===rx&&by===ry)) return true;
  const d=(pending[0]-tx)**2+((pending[1]-ty)*0.7)**2;      // grab slack for fingers
  return d < (pendingFort?16:9);
}
function setPending(x,y,isFort){
  pending=[x,y]; pendingFort=!!isFort; renderPlaceBar(); draw();
}
function clearPending(){
  if(!pending) return;
  pending=null; renderPlaceBar(); draw();
}
function commitPending(){
  if(!pending) return;
  const [x,y]=pending, isFort=pendingFort;
  const chk=validate(x,y,isFort);
  // Every remaining refusal is a hard game rule (terrain, a built structure, a claim,
  // the fort cap). The overridable case was the wall-corridor probe, dropped 2026-07-29.
  if(!chk.ok){ flash('Cannot place: '+chk.reason); return; }
  pushOps([{op:'add', kind:isFort?'fort':'ps', x, y, alli:planAlli}],
          (applied)=>({op:'del', id:(applied[0]||{}).id}));
  clearPending();
}
function renderPlaceBar(){
  let bar=document.getElementById('placeBar');
  if(!pending){ if(bar) bar.remove(); return; }
  const [x,y]=pending, isFort=pendingFort;
  const chk=validate(x,y,isFort);
  if(!bar){
    bar=document.createElement('div');
    bar.id='placeBar';
    document.body.appendChild(bar);
  }
  // two states now: legal, or a hard refusal (the overridable probe case is gone)
  const col = chk.ok ? 'var(--green)' : 'var(--red)';
  bar.innerHTML='<div style="margin-bottom:6px"><b>'+(isFort?'Fort':'Power Station')+'</b> '
    + x+';'+y+' <span style="color:var(--muted)">for</span> <b style="color:'+alliCol(planAlli)+'">'
    + esc(planAlli)+'</b></div>'
    +'<div style="font-size:11px;margin-bottom:8px;color:'+col+'">'
    + (chk.ok?'Legal spot &middot; drag the ghost to nudge it':esc(chk.reason))
    +'</div>'
    +'<div style="display:flex;gap:6px">'
    +'<button type="button" class="tbtn pb-ok"'+(chk.ok?'':' disabled')
    +' style="flex:1;'+(chk.ok?'border-color:var(--green);color:var(--green)':'opacity:.45')
    +'">Place here</button>'
    +'<button type="button" class="tbtn pb-no" style="flex:1">Cancel</button></div>';
  const ok=bar.querySelector('.pb-ok'); if(ok) ok.onclick=()=>commitPending();
  bar.querySelector('.pb-no').onclick=clearPending;
}
// ---- planned item: hit-test + edit in place ---------------------------------
// A planned structure is editable from the map itself, not just the sidebar row —
// on a phone the sidebar is a sheet, so tapping the thing you just placed has to work.
function planAt(tx,ty){
  const rx=Math.round(tx), ry=Math.round(ty);
  for(const p of plan){
    if(bodyTiles(p.x,p.y,p.fort).some(([bx,by])=>bx===rx&&by===ry)) return p;
  }
  // near miss: pick the closest within ~2 tiles so fat fingers still land
  let best=null,bd=1e9;
  plan.forEach(p=>{ const d=(p.x-tx)**2+((p.y-ty)*0.7)**2; if(d<bd&&d<9){bd=d;best=p;} });
  return best;
}
// ---- eraser: a swipe, not a tap. Dragging never pans while Erase is selected, it
// rubs out whatever it passes over — ink, notes, and planned structures — then sends
// one batch so a sweep is a single shared edit (and a single undo).
const ERASE_PX = 26;
function eraseSweep(pt){
  eraseCursor = pt;
  const [tx,ty] = pt;
  const st = strokeAt(tx,ty,ERASE_PX);
  if(st && !eraseHits['s'+st.id]) eraseHits['s'+st.id] = {op:{op:'strokeDel', id:st.id},
    undo:{op:'stroke', pts:st.pts, color:st.color, width:st.width}};
  const n = noteAt(tx,ty,ERASE_PX);
  if(n && !eraseHits['n'+n.id]) eraseHits['n'+n.id] = {op:{op:'noteDel', id:n.id},
    undo:{op:'note', x:n.x, y:n.y, text:n.text, color:n.color}};
  const it = planAt(tx,ty);
  if(it && !eraseHits['i'+it.id]) eraseHits['i'+it.id] = {op:{op:'del', id:it.id},
    undo:{op:'add', kind:it.fort?'fort':'ps', x:it.x, y:it.y, alli:it.alli}};
}
function eraseCommit(){
  const hits = Object.values(eraseHits);
  eraseHits = {}; eraseCursor = null;
  if(!hits.length){ draw(); return flash('Nothing under the eraser — sweep across it'); }
  const ops = hits.map(h=>h.op), undos = hits.map(h=>h.undo);
  // one shared edit for the whole sweep; undo puts all of it back
  pushOps(ops, ()=>({op:'__batch', ops:undos}));
  draw();
}
function isErasing(id, kind){ return !!eraseHits[kind+id]; }
