// ---- self test: does the captured terrain line up with the blocked-tile mask? ----
window.__st = function(){
  const out={corridors:JUMPS.length, east:0, west:0, needNewPS:0,
             forts:PLAN_ALLI.map(a=>{ const b=fortBudget(a);
               return a+' '+(b.built+b.planned)+'/'+b.cap+(b.dropped?' (-'+b.dropped+')':''); }).join(' · '),
             fortsFree:PLAN_ALLI.map(a=>fortBudget(a).free).join('/'),
             structs:S.length, fixed:FIX.length, alliances:D.alliances.length,
             blocked:0, terrain:{world:!!TERR.world.im.naturalWidth, district:!!TERR.district.im.naturalWidth}};
  for(let i=0;i<N;i++) if(gBlock[i]) out.blocked++;
  JUMPS.forEach(c=>{ out.east+=c.east.length; out.west+=c.west.length; if(c.needsNewPS) out.needNewPS++; });
  let bad=0, badW=0;
  JUMPS.forEach(c=>{
    c.east.forEach(([x,y])=>{ if(!validate(x,y,false).ok) bad++; });
    c.west.forEach(([x,y])=>{ if(!validate(x,y,false).ok) badW++; });
  });
  out.eastFailing=bad; out.westFailing=badW;
  out.texExample = JUMPS.some(c=>c.east.some(([x,y])=>x===133&&y===791)) ? 'OK' : 'MISSING';
  // per-server rollup, so the whole-map harvest can be checked at a glance
  const srv={};
  S.forEach(s=>{ const k='S'+(ASRV[s.owner]||0); srv[k]=(srv[k]||0)+1; });
  out.byServer=srv;
  // does the captured terrain sit where the blocked mask says? (home district sheet;
  // rock art is desaturated, grass is not - saturation is the discriminator)
  const T=TERR.district;
  if(T.im.naturalWidth){
    const c=document.createElement('canvas'); c.width=T.w; c.height=T.h;
    const g=c.getContext('2d'); g.drawImage(T.im,0,0);
    const mx0=Math.floor(108*112/T.wpp), mw=Math.ceil(42*112/T.wpp);
    const im=g.getImageData(mx0,0,mw,T.h).data;
    const rockAt=(x,y)=>{
      const mx=Math.round(x*112/T.wpp)-mx0, my=Math.round((y-750)*81/T.wpp);
      if(mx<0||mx>=mw||my<0||my>=T.h) return null;
      const i=(my*mw+mx)*4, r=im[i], gg=im[i+1], b=im[i+2];
      return (Math.max(r,gg,b)-Math.min(r,gg,b)) < 75;
    };
    const score=(dx,dy)=>{
      let hit=0,miss=0,fp=0,open=0;
      for(let y=756;y<=1324;y++) for(let x=112;x<=148;x++){
        if((x+y)%2) continue;
        const r=rockAt(x,y); if(r===null) continue;
        const j=idx(x+dx,y+dy); if(j<0||j>=N) continue;
        if(gBlock[j]){ r?hit++:miss++; } else { r?fp++:open++; }
      }
      return {onRock:+(hit/(hit+miss)*100).toFixed(1), falseRock:+(fp/(fp+open)*100).toFixed(1)};
    };
    out.mask = {aligned: score(0,0), shiftX_minus4: score(-4,0), shiftX_plus4: score(4,0),
                shiftY_minus4: score(0,-4), shiftY_plus4: score(0,4)};
  }
  return out;
};
